use WHMCS\Database\Capsule;
use CloudHost247\Theme\ThemeRepository;
use CloudHost247\Theme\AdminController;

function cloudhost247_theme_config()
{
    return array('name' => 'CloudHost247 Theme Manager', 'description' => 'Independent branding, navigation, content and SEO foundation.', 'version' => '1.1.0', 'author' => 'CloudHost247', 'language' => 'english', 'fields' => array());
}
function cloudhost247_theme_activate()
{
    try {
        if (!class_exists('CloudHost247\Foundation\Database\MigrationRunner')) throw new RuntimeException('Install the CloudHost247 Foundation files first.');
        $migrations = array(new \CloudHost247\Theme\Migrations\ThemeInitialMigration(), new \CloudHost247\Theme\Migrations\ThemeLocalizationMigration(), new \CloudHost247\Theme\Migrations\ThemeLandingContentMigration());
        $applied = (new MigrationRunner())->run('cloudhost247_theme', $migrations);
        return array('status' => 'success', 'description' => 'Theme settings and content repositories are ready. Applied: ' . (count($applied) ? implode(', ', $applied) : 'already current'));
    } catch (\Throwable $e) { return array('status' => 'error', 'description' => $e->getMessage()); }
}
function cloudhost247_theme_deactivate() { return array('status' => 'success', 'description' => 'Data retained. No WHMCS or legacy vendor tables were changed.'); }
function cloudhost247_theme_output($vars)
{
    $view = (new AdminController(new ThemeRepository()))->handle();
    $e = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
    echo '<div class="ch247-admin"><h2>CloudHost247 Theme Manager</h2><p class="alert alert-info">Independent theme manager. Every published item is supplied to the CloudHost247 client theme; no CloudHost247 runtime or licence is used.</p>';
    if ($view['notice']) echo '<div class="alert alert-success">' . $e($view['notice']) . '</div>';
    if ($view['error']) echo '<div class="alert alert-danger">' . $e($view['error']) . '</div>';
    echo '<ul class="nav nav-tabs"><li class="active"><a data-toggle="tab" href="#brand">Brand & layout</a></li><li><a data-toggle="tab" href="#content">Content manager</a></li><li><a data-toggle="tab" href="#inventory">Published inventory</a></li><li><a data-toggle="tab" href="#cms-audit">Audit history</a></li></ul><div class="tab-content" style="padding-top:20px">';
    echo '<div id="brand" class="tab-pane active"><form method="post"><input type="hidden" name="token" value="'.$e($view['token']).'"><input type="hidden" name="operation" value="settings"><div class="row">';
    $fields = array('brand_name'=>'Brand name','logo_url'=>'Logo URL (local or HTTPS)','primary_color'=>'Primary color','accent_color'=>'Accent color','font_family'=>'Font family','layout_width'=>'Maximum layout width','support_email'=>'Support email','hero_title'=>'Homepage heading','hero_text'=>'Homepage introduction','hero_cta_label'=>'Homepage button label','hero_cta_url'=>'Homepage button URL','footer_text'=>'Footer description','announcement_text'=>'Announcement text');
    foreach ($fields as $key => $label) echo '<div class="col-md-6 form-group"><label>'.$e($label).'</label><input class="form-control" name="'.$e($key).'" value="'.$e($view['settings'][$key]).'"></div>';
    echo '<div class="col-md-12 checkbox"><label><input type="hidden" name="show_announcement" value="0"><input type="checkbox" name="show_announcement" value="1"'.($view['settings']['show_announcement']==='1'?' checked':'').'> Display announcement bar</label></div></div><button class="btn btn-primary">Save theme settings</button></form></div>';
    echo '<div id="content" class="tab-pane"><form method="post"><input type="hidden" name="token" value="'.$e($view['token']).'"><div class="row"><div class="col-md-3 form-group"><label>Type</label><select class="form-control" name="content_type">';
    foreach (array('page','landing','section','navigation','banner','testimonial','footer') as $type) echo '<option value="'.$type.'">'.ucfirst($type).'</option>';
    echo '</select></div><div class="col-md-3 form-group"><label>Title</label><input required class="form-control" name="title"></div><div class="col-md-3 form-group"><label>Slug</label><input required pattern="[a-zA-Z0-9-]+" class="form-control" name="slug"></div><div class="col-md-3 form-group"><label>Order</label><input type="number" class="form-control" name="sort_order" value="0"></div><div class="col-md-6 form-group"><label>Summary</label><input class="form-control" name="summary"></div><div class="col-md-6 form-group"><label>Link URL</label><input class="form-control" name="url"></div><div class="col-md-6 form-group"><label>Image URL</label><input class="form-control" name="image_url"></div><div class="col-md-6 form-group"><label>Parent menu slug</label><input class="form-control" name="parent_slug"></div><div class="col-md-12 form-group"><label>Body (safe formatting tags allowed)</label><textarea rows="6" class="form-control" name="body"></textarea></div><div class="col-md-6 form-group"><label>SEO title</label><input class="form-control" name="seo_title"></div><div class="col-md-6 form-group"><label>SEO description</label><input class="form-control" name="seo_description"></div><div class="col-md-6 form-group"><label>Open Graph title</label><input class="form-control" name="og_title"></div><div class="col-md-6 form-group"><label>Open Graph description</label><input class="form-control" name="og_description"></div><div class="col-md-6 form-group"><label>Canonical URL</label><input class="form-control" name="canonical_url" placeholder="Local or HTTPS URL"></div><div class="col-md-12 checkbox"><label><input type="checkbox" name="published" value="1"> Published</label> <label><input type="checkbox" name="sitemap" value="1" checked> Include in sitemap</label> &nbsp; <label><input type="checkbox" name="open_new" value="1"> Open link in new tab</label></div></div><label><input type="checkbox" name="confirm" value="1"> Confirm if publishing</label> <button name="operation" value="preview" class="btn btn-default">Preview safely</button> <button name="operation" value="content" class="btn btn-primary">Create content</button></form>';if($view['preview']) echo '<div class="panel panel-default" style="margin-top:20px"><div class="panel-heading">Unpublished preview</div><div class="panel-body"><h2>'.$e($view['preview']['title']).'</h2><p>'.$e($view['preview']['summary']).'</p>'.$view['preview']['body'].'</div></div>';echo '<hr><h4>Localized content</h4><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($view['token']).'"><input type="hidden" name="operation" value="translation"><select name="content_id" class="form-control">';foreach($view['content'] as $item)echo '<option value="'.$e($item['id']).'">'.$e($item['title']).'</option>';echo '</select><input required name="locale" class="form-control" placeholder="Locale, e.g. french"><input required name="title" class="form-control" placeholder="Translated title"><input name="summary" class="form-control" placeholder="Translated summary"><textarea name="body" class="form-control" placeholder="Translated safe HTML"></textarea><input name="seo_title" class="form-control" placeholder="SEO title"><input name="seo_description" class="form-control" placeholder="SEO description"><button name="operation" value="localized_preview" class="btn btn-default">Preview translation</button> <button name="operation" value="translation" class="btn btn-primary">Save translation</button></form></div>';
    echo '<div id="inventory" class="tab-pane"><table class="table table-striped"><thead><tr><th>Type</th><th>Title</th><th>Slug</th><th>Order</th><th>Status</th><th></th></tr></thead><tbody>';
    foreach ($view['content'] as $item) { echo '<tr><td>'.$e($item['content_type']).'</td><td>'.$e($item['title']).'</td><td>'.$e($item['slug']).'</td><td>'.$e($item['sort_order']).'</td><td>'.($item['published']?'Published':'Draft').'</td><td><form method="post"><input type="hidden" name="token" value="'.$e($view['token']).'"><input type="hidden" name="operation" value="delete"><input type="hidden" name="id" value="'.$e($item['id']).'"><label><input type="checkbox" name="confirm" value="1" required> Confirm</label><button class="btn btn-xs btn-danger">Delete</button></form></td></tr>'; }
    echo '</tbody></table></div><div id="cms-audit" class="tab-pane"><div class="table-responsive"><table class="table"><thead><tr><th>Timestamp</th><th>Action</th><th>Result</th><th>Correlation ID</th><th>Details</th></tr></thead><tbody>';foreach($view['audit'] as $audit)echo'<tr><td>'.$e($audit->created_at).'</td><td>'.$e($audit->action).'</td><td>'.$e($audit->result).'</td><td><code>'.$e($audit->correlation_id).'</code></td><td><details><summary>Redacted change</summary><pre>'.$e($audit->before_json).'</pre><pre>'.$e($audit->after_json).'</pre></details></td></tr>';echo'</tbody></table></div></div></div></div>';
}
